// Normalizes whatever Apps Script sent into the exact field names the
// shared Jira sub-workflow expects, and tags the Source so the resulting
// Jira ticket/comment clearly shows this came from a human decision, not
// the automated LLM comparison.

const body = $json.body || $json;

return {
  json: {
    "Test Case ID": body["Test Case ID"],
    "Story ID": body["Story ID"],
    "Unique Test Case Key": body["Unique Test Case Key"],
    "Expected Result": body["Expected Result"],
    "Actual Result": body["Actual Result"],
    "Execution Status": "Fail",
    "Confidence Score": "Manual",
    "Comments": body["Comments"] || `Manually reviewed and marked Fail by ${body["ReviewedBy"] || "a team member"}.`,
    "Source": "Manual Review"
  }
};
